/**
 * The Cloudflare site build, generated: `gen.cloudflare/build.sh` installs
 * the pinned Rust, documents the workspace, and runs the generator. The
 * Cloudflare dashboard names the script as the build command, and the script
 * is the one place its steps are written down — in the repository, reviewed,
 * and regenerated by `npm run gen` like every other `gen.*` output.
 *
 * **Generated rather than written**, because of the version in it. The build
 * image carries no Rust, so the script installs one, and the toolchain it
 * names is {@link rust} from `fjs/ci/config` — the constant the shared shell
 * and the platform matrix also take. Written out in full, a bump of the pin
 * is a diff in this script that the drift check guards, as it is in
 * `gen.nix/flake.nix`; read at run time, nothing committed would say which
 * Rust the site is built with.
 *
 * @module
 *
 * @import { Effect, IoChannel } from '../../effects/types.ts'
 * @import { Mkdir, NodeProgram, Rm, WriteBytes, WriteFile } from '../../effects/node/types.ts'
 */

import { rust } from '../../ci/config/module.f.js'
import { step } from '../../effects/module.f.mjs'
import { exitStep, mkdir, writeUtf8File } from '../../effects/node/module.f.mjs'

/**
 * The generated directory, beside `gen.nix/` at the repository root, where
 * `wrangler.jsonc`, `.assetsignore` and `.node-version` already are for
 * Cloudflare's sake.
 *
 * @type {string}
 */
export const generatedDirectory = 'gen.cloudflare'

/** The script, as the dashboard's build command names it: `sh ./gen.cloudflare/build.sh`. */
/** @type {string} */
export const buildPath = `${generatedDirectory}/build.sh`

/**
 * The script's text.
 *
 * `rustup-init`, the installer `rustup`'s one-line install fetches, fetched
 * directly: Cloudflare builds on one host, x86-64 Linux, so the target is
 * written rather than detected, and it is one download rather than a script
 * that downloads. Saved to a file and then run — not piped into `sh`, whose
 * exit status would be the pipeline's whatever `curl` answered, so a refused
 * download would be a silent one. It goes under `$HOME`, which on the build
 * image is a fresh container's, and runs non-interactively with the smallest
 * profile that carries `cargo` and `rustdoc`, exactly the pinned toolchain,
 * and no edit to a shell profile nothing would read. `cargo` is then run by
 * its path there, not through a `PATH` the installer was told not to touch.
 * `--no-deps` documents the workspace's crates and not their dependencies.
 *
 * `set -e` makes the first failing step the script's result, so a build that
 * could not install or document does not publish a site without the docs.
 *
 * The script calls external tools — `curl`, `chmod`, `rustup-init` and
 * `cargo` — which the repository owner approved for this one script
 * ([`AGENTS.md` §6](../../../AGENTS.md#6-external-tools)). Its proof pins the
 * text exactly, so no tool joins it unseen.
 *
 * @type {() => string}
 */
export const buildText = () => `#!/bin/sh
set -e
curl --proto '=https' --tlsv1.2 -sSf https://static.rust-lang.org/rustup/dist/x86_64-unknown-linux-gnu/rustup-init -o "$HOME/rustup-init"
chmod +x "$HOME/rustup-init"
"$HOME/rustup-init" -y --profile minimal --default-toolchain ${rust} --no-modify-path
"$HOME/.cargo/bin/cargo" doc --no-deps --workspace
npm run website
`

/**
 * Writes the script. No mode is set: Cloudflare runs it through `sh`, as CI
 * runs `gen.nix/run`, and the effects layer sets none.
 *
 * @type {Effect<Mkdir | Rm | WriteBytes | WriteFile, void, IoChannel>}
 */
export const cloudflare = step(
    mkdir(generatedDirectory, { recursive: true }),
    () => writeUtf8File(buildPath, buildText()))

/** @type {NodeProgram} */
export const main = _options => exitStep(cloudflare)
